//! Hermes engine backend for the v8 C-ABI compat layer (spike).
//!
//! Cycle 0/1 scaffold: this module makes `cargo build --features hermes`
//! compile and link with a pure-Rust stub backend and zero Hermes dependency.
//! Every `v8__*`/`v8_inspector__*` symbol the vendored rusty_v8 surface
//! declares is defined in `shims` as an `unimplemented!()` no-arg stub
//! (auto-generated by tools/gen_hermes_shims.sh); `cppgc__*` stubs live in
//! `misc`. Nothing here runs real JavaScript yet. See
//! docs/hermes-spike/NOTES.md ("Cycle 0 - integration surface") for the plan:
//! a real backend is a clone of src/quickjs/'s arena-handle shape (Hermes JSI
//! values are NaN-boxed structs like QuickJS's `JSValue`, not JSC-style
//! pointer punning), built against Hermes's C++ JSI through an extern "C"
//! bridge.

mod misc;
mod shims;
